func nextSelfImposedBudget(current, parsedLimit, sentBytes int64, abortedEarly bool) int64 {
	if abortedEarly {
		return current
	}
	candidate := int64(0)
	switch {
	case parsedLimit > 0:
		candidate = parsedLimit
	case sentBytes > 0:
		candidate = sentBytes
	}
	if candidate <= 0 {
		return current
	}
	if current == 0 || candidate < current {
		return candidate
	}
	return current
}

